function wire(){tlBind();if(section==='patients'&&window.SSMPDReceptionPatientSearch)window.SSMPDReceptionPatientSearch.bind(host,{live:data.workspace.mode==='live',workspace:workspace,onSelect:async function(p){if(data.workspace.mode!=='live'){if(window.SSMPDRenderPatients)window.SSMPDRenderPatients.openPatientById(p.id);return;}var linked=await command('patient_attach',{patient_id:p.id},crypto.randomUUID());await load();bookModal(linked.id);}});var ws=host.querySelector('[data-rx-workspace]');if(ws)ws.onchange=function(){workspace=ws.value;section=null;load();};host.querySelectorAll('[data-rx-section]').forEach(function(b){b.onclick=function(){section=b.dataset.rxSection;draw();host.querySelector('[data-rx-heading]').focus();};});host.querySelectorAll('[data-rx-action]').forEach(function(b){b.onclick=function(){act(b.dataset.rxAction,b.dataset.id);};});var period=host.querySelector('.rx-period');if(period)period.onsubmit=function(e){e.preventDefault();from=period.elements.from.value;to=period.elements.to.value;load();};var search=host.querySelector('[data-rx-search]');if(search)search.oninput=function(){query=search.value;var pos=search.selectionStart;draw();var next=host.querySelector('[data-rx-search]');next.focus();next.setSelectionRange(pos,pos);};}
